-- 0028 — канонические строки справочников ЦФО, снятые дампом из наполненной БД
-- (источник: var/plan/«РБ ВСЕ ЦФО (1).xlsx», распарсено локально в UI/импорте —
-- в коде их нет, EnsureSeed отдаёт лишь MP-подмножество CFOSeed()). Без этой
-- миграции на проде dir_cfo был бы почти пустым.
--
-- Идемпотентно: DELETE строк справочника + INSERT дампа (перезапуск даёт тот же
-- результат, перекрывает код-сид). FK на plans_directory_row нет; связь job_position
-- с ЦФО идёт по external_id (переживает переимпорт, см. 0024). directory_id
-- резолвится по code — id в каждой среде свой.

-- dir_cfo
DELETE FROM plans_directory_row WHERE directory_id = (SELECT id FROM plans_directory WHERE code = 'dir_cfo');
