-- dir_cfo_type
DELETE FROM plans_directory_row WHERE directory_id = (SELECT id FROM plans_directory WHERE code = 'dir_cfo_type');
INSERT INTO plans_directory_row (directory_id, external_id, payload_json)
SELECT d.id, v.ext, v.payload FROM plans_directory d
CROSS JOIN (VALUES
    ('магазин', '{"code": "магазин", "name": "магазин"}'::jsonb),
    ('отдел', '{"code": "отдел", "name": "отдел"}'::jsonb),
    ('производство', '{"code": "производство", "name": "производство"}'::jsonb)
) AS v(ext, payload)
WHERE d.code = 'dir_cfo_type';
UPDATE plans_directory SET sync_status='ok' WHERE code='dir_cfo_type';
